}
.btn-outline:hover { background: var(--forest); color: var(--white); }
.btn-green { background: var(--green); color: var(--white); }
.btn-green:hover { background: var(--green-dark); color: var(--white); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }

