/* GreenBean Coffee — shared styles */
:root {
  --green: #00824A;
  --green-dark: #006B3C;
  --forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FAF3E8;
  --coffee: #4A2E1F;
  --coffee-warm: #6B4423;
  --bg: #FCFAF6;
  --text: #1E2A24;
  --text-muted: #5A6760;
  --border: #E5DFD3;
  --white: #FFFFFF;
  --shadow-sm: 0 2px 8px rgba(50, 70, 47, 0.06);
  --shadow-md: 0 6px 20px rgba(50, 70, 47, 0.10);
  --shadow-lg: 0 12px 40px rgba(50, 70, 47, 0.14);
  --radius-sm: 10px;
  --radius-md: 18px;
  --radius-lg: 28px;
  --radius-pill: 999px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4 {
  font-family: 'Fraunces', 'Playfair Display', Georgia, serif;
  font-weight: 600;
  line-height: 1.15;
  color: var(--forest);
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.4rem, 5vw, 4rem); }
h2 { font-size: clamp(1.8rem, 3.5vw, 2.6rem); }
h3 { font-size: clamp(1.3rem, 2vw, 1.6rem); }

a { color: var(--green); text-decoration: none; transition: color .2s ease; }
a:hover { color: var(--green-dark); }

img { max-width: 100%; display: block; }

button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 24px;
}

/* === Buttons === */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 26px;
  border-radius: var(--radius-pill);
  font-weight: 600;
  font-size: 0.95rem;
  transition: all .2s ease;
  border: 1.5px solid transparent;
  cursor: pointer;
  white-space: nowrap;
}
.btn-primary {
  background: var(--forest);
  color: var(--white);
}
.btn-primary:hover { background: #1f2f1c; color: var(--white); transform: translateY(-1px); }
.btn-outline {
  background: transparent;
  color: var(--forest);
  border-color: var(--forest);
}
.btn-outline:hover { background: var(--forest); color: var(--white); }
.btn-green { background: var(--green); color: var(--white); }
.btn-green:hover { background: var(--green-dark); color: var(--white); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }

/* === Header === */
.site-header {
  position: sticky;
  top: 0;
  background: var(--white);
  border-bottom: 1px solid var(--border);
  z-index: 100;
  backdrop-filter: blur(10px);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 24px;
  max-width: 1320px;
  margin: 0 auto;
  gap: 24px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'Fraunces', serif;
  font-weight: 700;
  font-size: 1.3rem;
  color: var(--forest);
}
.logo-mark {
  width: 40px; height: 40px;
  background: var(--green);
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--white);
  font-size: 1.1rem;
}
.nav-primary {
  display: flex;
  gap: 4px;
  flex: 1;
  margin-left: 20px;
}
.nav-primary a {
  padding: 8px 14px;
  border-radius: var(--radius-pill);
  font-weight: 600;
  font-size: 0.92rem;
  color: var(--forest);
}
.nav-primary a:hover, .nav-primary a.active {
  background: var(--cream-light);
  color: var(--forest);
}
.nav-account { display: flex; gap: 8px; align-items: center; }
.icon-btn {
  width: 40px; height: 40px;
  border-radius: 50%;
  display: grid; place-items: center;
  color: var(--forest);
}
.icon-btn:hover { background: var(--cream-light); }

.menu-toggle { display: none; }

/* === Hero === */
.hero {
  background: linear-gradient(135deg, #00824A 0%, #006B3C 100%);
  color: var(--white);
  position: relative;
  overflow: hidden;
  padding: 80px 0 100px;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 80% 20%, rgba(243,206,161,0.25), transparent 50%),
              radial-gradient(circle at 20% 80%, rgba(50,70,47,0.4), transparent 50%);
}
.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 60px;
}
.hero h1 { color: var(--white); margin-bottom: 24px; }
.hero p { font-size: 1.15rem; margin-bottom: 32px; opacity: .92; max-width: 520px; }
.hero-image {
  height: 460px;
  border-radius: var(--radius-lg);
  background:
    linear-gradient(135deg, rgba(243,206,161,0.85), rgba(74,46,31,0.7)),
    radial-gradient(circle at 30% 30%, #f3cea1 0%, #c8956a 40%, #4a2e1f 100%);
  box-shadow: var(--shadow-lg);
  position: relative;
  overflow: hidden;
}
.hero-image::after {
  content: '☕';
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: 9rem;
  opacity: 0.4;
}
.hero .btn-primary { background: var(--white); color: var(--forest); }
.hero .btn-primary:hover { background: var(--cream); }

/* === Sections === */
section { padding: 70px 0; }
section.tight { padding: 50px 0; }

.section-title { text-align: center; margin-bottom: 14px; }
.section-subtitle { text-align: center; color: var(--text-muted); max-width: 680px; margin: 0 auto 50px; font-size: 1.05rem; }

/* === Promo cards === */
.promo-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
}
.promo-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 44px 40px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
  transition: transform .2s ease, box-shadow .2s ease;
}
.promo-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.promo-card.dark { background: var(--forest); color: var(--white); }
.promo-card.dark h2, .promo-card.dark h3 { color: var(--white); }
.promo-card.cream { background: var(--cream); border-color: transparent; }
.promo-card.green { background: var(--green); color: var(--white); }
.promo-card.green h2, .promo-card.green h3 { color: var(--white); }

.promo-card h2, .promo-card h3 { margin-bottom: 14px; }
.promo-card p { margin-bottom: 22px; }

.promo-image {
  height: 200px;
  border-radius: var(--radius-md);
  margin-bottom: 24px;
  background: linear-gradient(135deg, var(--cream), #d4a574);
}
.promo-image.citrus { background: linear-gradient(135deg, #ffd166, #ff9a3c); }
.promo-image.afternoon { background: linear-gradient(135deg, #6b4423, #c8956a); }
.promo-image.ai { background: linear-gradient(135deg, #32462f, #00824a); }
.promo-image.mango { background: linear-gradient(135deg, #ffb15c, #ff7a3d, #d84d2c); }
.promo-image.spring { background: linear-gradient(135deg, #c8a8d4, #8b6fa3, #5d4677); }
.promo-image.nondairy { background: linear-gradient(135deg, #faf3e8, #e8d4b0); }

.full-promo {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
}
.full-promo .promo-image { height: 100%; min-height: 320px; border-radius: 0; margin: 0; }
.full-promo .promo-text { padding: 56px 48px; display: flex; flex-direction: column; justify-content: center; }
.full-promo.flip .promo-image { order: 2; }

/* === Cookie banner === */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 24px;
  right: 24px;
  max-width: 540px;
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--border);
  padding: 24px 28px;
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.cookie-banner.hidden { display: none; }
.cookie-banner h4 { font-size: 1.1rem; color: var(--forest); }
.cookie-banner p { font-size: 0.92rem; color: var(--text-muted); }
.cookie-actions { display: flex; gap: 10px; flex-wrap: wrap; }

/* === Footer === */
.site-footer {
  background: var(--forest);
  color: #d8dcd5;
  padding: 70px 0 30px;
  margin-top: 80px;
}
.site-footer h4 {
  color: var(--white);
  font-family: 'Inter', sans-serif;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 20px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 40px;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 12px; }
.footer-col a {
  color: #b8c0b6;
  font-size: 0.92rem;
  transition: color .2s ease;
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  margin-top: 60px;
  padding-top: 28px;
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px;
  font-size: 0.85rem;
  color: #90998d;
}
.footer-toggle { display: none; }

/* === Breadcrumb === */
.breadcrumb {
  padding: 18px 0;
  font-size: 0.9rem;
  color: var(--text-muted);
}
.breadcrumb a { color: var(--text-muted); }
.breadcrumb a:hover { color: var(--green); }
.breadcrumb .sep { margin: 0 8px; }

/* === Menu page === */
.menu-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 60px;
  padding: 30px 0 60px;
}
.menu-sidebar h3 {
  font-family: 'Inter', sans-serif;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  margin: 26px 0 12px;
}
.menu-sidebar h3:first-child { margin-top: 0; }
.menu-sidebar ul { list-style: none; }
.menu-sidebar li { margin-bottom: 6px; }
.menu-sidebar a {
  display: block;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  color: var(--forest);
  font-weight: 500;
  font-size: 0.95rem;
  transition: background .15s ease;
}
.menu-sidebar a:hover, .menu-sidebar a.active {
  background: var(--cream-light);
  color: var(--green-dark);
}
.menu-section { margin-bottom: 60px; }
.menu-section h2 { margin-bottom: 6px; }
.menu-section .sub { color: var(--text-muted); margin-bottom: 30px; }
.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 28px;
}
.menu-item {
  cursor: pointer;
  transition: transform .2s ease;
}
.menu-item:hover { transform: translateY(-3px); }
.menu-item .thumb {
  height: 200px;
  border-radius: var(--radius-md);
  margin-bottom: 14px;
  background: linear-gradient(135deg, #f3cea1, #c8956a);
  box-shadow: var(--shadow-sm);
}
.menu-item .thumb.green { background: linear-gradient(135deg, #a8d4b0, #00824a); }
.menu-item .thumb.purple { background: linear-gradient(135deg, #c8a8d4, #5d4677); }
.menu-item .thumb.brown { background: linear-gradient(135deg, #c8956a, #4a2e1f); }
.menu-item .thumb.pink { background: linear-gradient(135deg, #ffc0c0, #d84d6f); }
.menu-item .thumb.yellow { background: linear-gradient(135deg, #ffe066, #ff9a3c); }
.menu-item .thumb.cream-bg { background: linear-gradient(135deg, #faf3e8, #f3cea1); }
.menu-item h4 {
  font-family: 'Inter', sans-serif;
  font-size: 1rem;
  color: var(--text);
  font-weight: 600;
}

/* === Rewards page === */
.rewards-hero {
  background: linear-gradient(135deg, #32462F 0%, #00824A 100%);
  color: var(--white);
  padding: 90px 0;
  text-align: center;
}
.rewards-hero h1 { color: var(--white); }
.rewards-hero p { font-size: 1.15rem; opacity: .9; max-width: 640px; margin: 20px auto 30px; }
.star { color: #FFD166; }

.steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.step-card {
  background: var(--white);
  padding: 36px 30px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  text-align: center;
}
.step-num {
  width: 48px; height: 48px;
  border-radius: 50%;
  background: var(--green);
  color: var(--white);
  font-weight: 700;
  display: grid; place-items: center;
  margin: 0 auto 18px;
  font-family: 'Fraunces', serif;
  font-size: 1.3rem;
}
.step-card h3 { margin-bottom: 10px; font-size: 1.2rem; }

.tiers {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.tier {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 36px 30px;
  border: 1px solid var(--border);
  position: relative;
  transition: transform .2s ease;
}
.tier:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.tier-badge {
  display: inline-block;
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 16px;
}
.tier.green .tier-badge { background: #d8f0e0; color: var(--green-dark); }
.tier.gold .tier-badge { background: #fcecc4; color: #8b6f1c; }
.tier.reserve .tier-badge { background: #2a1f1a; color: var(--cream); }
.tier.reserve { background: linear-gradient(135deg, #32462f, #1a2618); color: #d8dcd5; border-color: transparent; }
.tier.reserve h3 { color: var(--white); }
.tier h3 { font-size: 1.4rem; margin-bottom: 6px; }
.tier .threshold { font-size: 0.95rem; color: var(--text-muted); margin-bottom: 22px; }
.tier.reserve .threshold { color: #b8c0b6; }
.tier ul { list-style: none; }
.tier li { padding: 10px 0; border-top: 1px solid var(--border); font-size: 0.95rem; }
.tier.reserve li { border-color: rgba(255,255,255,0.1); }
.tier li::before { content: '★ '; color: var(--green); font-size: 0.9em; }
.tier.reserve li::before { color: var(--cream); }

/* Rewards tabs */
.tabs {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  border: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
}
.tab-list {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  border-bottom: 1px solid var(--border);
  padding-bottom: 24px;
  margin-bottom: 30px;
}
.tab-btn {
  padding: 10px 20px;
  border-radius: var(--radius-pill);
  background: var(--cream-light);
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--forest);
  border: 2px solid transparent;
  transition: all .2s ease;
}
.tab-btn:hover { background: var(--cream); }
.tab-btn.active {
  background: var(--green);
  color: var(--white);
  border-color: var(--green);
}
.tab-panel { display: none; }
.tab-panel.active {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
  animation: fade .3s ease;
}
@keyframes fade { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
.tab-panel .panel-img {
  height: 240px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--cream), var(--coffee-warm));
}
.tab-panel h3 { font-size: 1.5rem; margin-bottom: 10px; }
.tab-panel .value-tag {
  display: inline-block;
  background: var(--cream-light);
  color: var(--forest);
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  font-size: 0.85rem;
  font-weight: 700;
  margin-top: 14px;
}

.partnerships {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.partner-card {
  background: var(--white);
  padding: 36px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  display: flex;
  gap: 24px;
  align-items: center;
}
.partner-logo {
  width: 76px; height: 76px;
  border-radius: 50%;
  background: var(--cream-light);
  display: grid; place-items: center;
  font-size: 1.6rem;
  flex-shrink: 0;
  color: var(--forest);
  font-weight: 700;
}

/* === Gift cards === */
.gift-hero {
  background: linear-gradient(135deg, var(--cream), #e8b88a);
  padding: 70px 0;
}
.gift-hero-inner { display: grid; grid-template-columns: 1.2fr 1fr; gap: 50px; align-items: center; }
.gift-hero h1 { color: var(--coffee); }
.gift-hero p { font-size: 1.1rem; margin: 18px 0 28px; color: var(--coffee-warm); }
.gift-stack {
  position: relative;
  height: 320px;
}
.gift-card-design {
  position: absolute;
  width: 230px;
  height: 150px;
  border-radius: 14px;
  box-shadow: var(--shadow-md);
  display: grid;
  place-items: center;
  color: var(--white);
  font-family: 'Fraunces', serif;
  font-size: 1.15rem;
  text-align: center;
  padding: 10px;
}
.gift-stack .gift-card-design:nth-child(1) { background: linear-gradient(135deg, #00824A, #006B3C); top: 10px; left: 0; transform: rotate(-8deg); }
.gift-stack .gift-card-design:nth-child(2) { background: linear-gradient(135deg, #d84d6f, #a32a4d); top: 60px; left: 100px; transform: rotate(2deg); }
.gift-stack .gift-card-design:nth-child(3) { background: linear-gradient(135deg, #4a2e1f, #6b4423); top: 130px; left: 30px; transform: rotate(-3deg); }

.carousel { position: relative; padding: 0 60px; }
.carousel-track {
  display: flex;
  gap: 22px;
  overflow: hidden;
  scroll-behavior: smooth;
}
.carousel-card {
  flex: 0 0 calc((100% - 66px) / 4);
  min-width: 0;
}
.gift-thumb {
  aspect-ratio: 1.6 / 1;
  border-radius: var(--radius-md);
  display: grid;
  place-items: center;
  color: var(--white);
  font-family: 'Fraunces', serif;
  font-size: 1.1rem;
  text-align: center;
  padding: 16px;
  box-shadow: var(--shadow-sm);
  transition: transform .2s ease, box-shadow .2s ease;
  cursor: pointer;
}
.gift-thumb:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.carousel-card p {
  text-align: center;
  margin-top: 10px;
  font-size: 0.9rem;
  color: var(--text-muted);
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px; height: 44px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: var(--shadow-md);
  display: grid;
  place-items: center;
  color: var(--forest);
  font-size: 1.2rem;
  z-index: 5;
  border: 1px solid var(--border);
  transition: background .2s ease;
}
.carousel-btn:hover { background: var(--cream-light); }
.carousel-btn:disabled { opacity: 0.4; cursor: not-allowed; }
.carousel-btn.prev { left: 0; }
.carousel-btn.next { right: 0; }

.category-section { margin-bottom: 70px; }
.category-section h3 {
  font-family: 'Fraunces', serif;
  font-size: 1.6rem;
  margin-bottom: 22px;
}

/* Color palette for gift card thumbs */
.gc-1 { background: linear-gradient(135deg, #00824A, #006B3C); }
.gc-2 { background: linear-gradient(135deg, #f3cea1, #c8956a); color: #4a2e1f !important; }
.gc-3 { background: linear-gradient(135deg, #d84d6f, #8b1f3f); }
.gc-4 { background: linear-gradient(135deg, #5d4677, #32264a); }
.gc-5 { background: linear-gradient(135deg, #ffd166, #ff9a3c); color: #4a2e1f !important; }
.gc-6 { background: linear-gradient(135deg, #4a2e1f, #2a1810); }
.gc-7 { background: linear-gradient(135deg, #00824A, #32462F); }
.gc-8 { background: linear-gradient(135deg, #c8a8d4, #8b6fa3); }
.gc-9 { background: linear-gradient(135deg, #ff7a9c, #d84d6f); }
.gc-10 { background: linear-gradient(135deg, #6b4423, #4a2e1f); }
.gc-11 { background: linear-gradient(135deg, #32462F, #1a2618); }
.gc-12 { background: linear-gradient(135deg, #00824A, #f3cea1); }

.business-gifting {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 50px;
  align-items: center;
  background: var(--forest);
  color: var(--white);
  border-radius: var(--radius-lg);
  padding: 56px;
}
.business-gifting h2 { color: var(--white); }
.business-gifting p { margin: 18px 0 26px; opacity: 0.92; }
.business-image {
  height: 280px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--cream), var(--coffee-warm));
}

.egift-info { background: var(--cream-light); }
.egift-grid { display: grid; grid-template-columns: 1.2fr 1fr; gap: 50px; align-items: center; }

.faq-item {
  background: var(--white);
  border-radius: var(--radius-md);
  padding: 24px 28px;
  margin-bottom: 14px;
  border: 1px solid var(--border);
}
.faq-item summary {
  font-weight: 600;
  font-size: 1.05rem;
  cursor: pointer;
  list-style: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--forest);
}
.faq-item summary::after { content: '+'; font-size: 1.4rem; color: var(--green); transition: transform .2s; }
.faq-item[open] summary::after { transform: rotate(45deg); }
.faq-item p { padding-top: 14px; color: var(--text-muted); }

/* === Store locator === */
.locator-controls {
  background: var(--white);
  border-bottom: 1px solid var(--border);
  padding: 24px 0;
}
.controls-inner {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  align-items: center;
}
.toggle-group {
  display: inline-flex;
  background: var(--cream-light);
  border-radius: var(--radius-pill);
  padding: 4px;
  gap: 2px;
}
.toggle-btn {
  padding: 8px 22px;
  border-radius: var(--radius-pill);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--forest);
  transition: all .2s ease;
}
.toggle-btn.active { background: var(--white); box-shadow: var(--shadow-sm); color: var(--green-dark); }

.search-box {
  flex: 1;
  min-width: 280px;
  position: relative;
}
.search-input {
  width: 100%;
  padding: 14px 20px 14px 48px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-pill);
  font-family: inherit;
  font-size: 0.95rem;
  background: var(--bg);
  transition: border-color .2s ease;
}
.search-input:focus {
  outline: none;
  border-color: var(--green);
  background: var(--white);
}
.search-icon {
  position: absolute;
  left: 18px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
}
.suggestions {
  position: absolute;
  top: calc(100% + 6px);
  left: 0; right: 0;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  z-index: 10;
  display: none;
  overflow: hidden;
}
.suggestions.show { display: block; }
.suggestion {
  padding: 12px 18px;
  cursor: pointer;
  border-bottom: 1px solid var(--border);
  font-size: 0.92rem;
}
.suggestion:last-child { border: none; }
.suggestion:hover { background: var(--cream-light); }

.filter-btn {
  padding: 12px 22px;
  border-radius: var(--radius-pill);
  border: 1.5px solid var(--border);
  background: var(--white);
  color: var(--forest);
  font-weight: 600;
  font-size: 0.92rem;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.filter-btn:hover, .filter-btn.active { border-color: var(--green); color: var(--green-dark); }

.filter-panel {
  display: none;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 24px;
  margin-top: 16px;
  box-shadow: var(--shadow-sm);
}
.filter-panel.show { display: block; }
.filter-group h4 { font-family: 'Inter', sans-serif; font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-muted); margin-bottom: 12px; }
.filter-options { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 18px; }
.filter-chip {
  padding: 8px 14px;
  border-radius: var(--radius-pill);
  background: var(--cream-light);
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--forest);
  cursor: pointer;
  border: 1.5px solid transparent;
  transition: all .15s ease;
}
.filter-chip:hover { background: var(--cream); }
.filter-chip.active { background: var(--green); color: var(--white); border-color: var(--green); }

.locator-layout {
  display: grid;
  grid-template-columns: 420px 1fr;
  height: calc(100vh - 200px);
  min-height: 600px;
}
.results-list {
  overflow-y: auto;
  padding: 24px;
  background: var(--white);
  border-right: 1px solid var(--border);
}
.results-count {
  font-size: 0.88rem;
  color: var(--text-muted);
  margin-bottom: 16px;
}
.store-card {
  padding: 20px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  margin-bottom: 14px;
  cursor: pointer;
  transition: all .2s ease;
}
.store-card:hover { border-color: var(--green); box-shadow: var(--shadow-sm); }
.store-card h4 { font-family: 'Inter', sans-serif; font-size: 1rem; margin-bottom: 6px; color: var(--forest); }
.store-card .addr { color: var(--text-muted); font-size: 0.9rem; margin-bottom: 8px; }
.store-card .hours { color: var(--green); font-weight: 600; font-size: 0.85rem; margin-bottom: 10px; }
.store-card .features { display: flex; gap: 6px; flex-wrap: wrap; }
.store-card .feature {
  background: var(--cream-light);
  color: var(--forest);
  padding: 3px 10px;
  border-radius: var(--radius-pill);
  font-size: 0.75rem;
  font-weight: 600;
}

.map-view {
  background:
    radial-gradient(circle at 30% 40%, rgba(0,130,74,0.08), transparent 30%),
    radial-gradient(circle at 70% 60%, rgba(0,130,74,0.06), transparent 30%),
    linear-gradient(135deg, #eaf2e8 0%, #d8e6d2 100%);
  position: relative;
  overflow: hidden;
}
.map-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(50,70,47,0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(50,70,47,0.06) 1px, transparent 1px);
  background-size: 40px 40px;
}
.map-pin {
  position: absolute;
  width: 36px; height: 36px;
  background: var(--green);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  box-shadow: var(--shadow-md);
  display: grid;
  place-items: center;
  color: var(--white);
  cursor: pointer;
}
.map-pin::after {
  content: '☕';
  transform: rotate(45deg);
  font-size: 1rem;
}
.map-pin:hover { background: var(--green-dark); transform: rotate(-45deg) scale(1.1); }

/* === Responsive === */
@media (max-width: 960px) {
  .nav-primary { display: none; }
  .menu-toggle { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; color: var(--forest); }
  .menu-toggle:hover { background: var(--cream-light); }
  .hero { padding: 60px 0 70px; }
  .hero-inner { grid-template-columns: 1fr; }
  .hero-image { height: 280px; }
  .promo-grid, .full-promo, .gift-hero-inner, .egift-grid, .business-gifting, .partnerships, .tab-panel.active { grid-template-columns: 1fr; }
  .full-promo .promo-text { padding: 36px 28px; }
  .full-promo .promo-image { min-height: 220px; }
  .menu-layout { grid-template-columns: 1fr; gap: 30px; }
  .menu-sidebar { background: var(--white); padding: 24px; border-radius: var(--radius-md); border: 1px solid var(--border); }
  .steps, .tiers { grid-template-columns: 1fr; }
  .business-gifting { padding: 36px 28px; }
  .carousel-card { flex: 0 0 calc((100% - 22px) / 2); }
  .locator-layout { grid-template-columns: 1fr; height: auto; }
  .map-view { height: 400px; }
  .results-list { border-right: none; border-bottom: 1px solid var(--border); }

  /* Footer accordion */
  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col {
    border-bottom: 1px solid rgba(255,255,255,0.1);
  }
  .footer-col h4 {
    margin: 0;
    padding: 18px 0;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .footer-toggle { display: inline; transition: transform .2s ease; font-size: 1.4rem; font-weight: 400; }
  .footer-col.expanded .footer-toggle { transform: rotate(45deg); }
  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height .3s ease, padding .3s ease;
    padding-bottom: 0;
  }
  .footer-col.expanded ul {
    max-height: 600px;
    padding-bottom: 18px;
  }
}

@media (max-width: 600px) {
  .container { padding: 0 16px; }
  section { padding: 50px 0; }
  .carousel { padding: 0 44px; }
  .carousel-card { flex: 0 0 100%; }
  .tab-list { gap: 6px; }
  .tab-btn { padding: 8px 14px; font-size: 0.85rem; }
  .gift-stack { height: 260px; }
  .gift-card-design { width: 180px; height: 120px; font-size: 0.95rem; }
}

/* GreenBean Coffee — shared styles */
:root {
  --green: #00824A;
  --green-dark: #006B3C;
  --forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FAF3E8;
  --coffee: #4A2E1F;
  --coffee-warm: #6B4423;
  --bg: #FCFAF6;
  --text: #1E2A24;
  --text-muted: #5A6760;
  --border: #E5DFD3;
  --white: #FFFFFF;
  --shadow-sm: 0 2px 8px rgba(50, 70, 47, 0.06);
  --shadow-md: 0 6px 20px rgba(50, 70, 47, 0.10);
  --shadow-lg: 0 12px 40px rgba(50, 70, 47, 0.14);
  --radius-sm: 10px;
  --radius-md: 18px;
  --radius-lg: 28px;
  --radius-pill: 999px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4 {
  font-family: 'Fraunces', 'Playfair Display', Georgia, serif;
  font-weight: 600;
  line-height: 1.15;
  color: var(--forest);
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.4rem, 5vw, 4rem); }
h2 { font-size: clamp(1.8rem, 3.5vw, 2.6rem); }
h3 { font-size: clamp(1.3rem, 2vw, 1.6rem); }

a { color: var(--green); text-decoration: none; transition: color .2s ease; }
a:hover { color: var(--green-dark); }

img { max-width: 100%; display: block; }

button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 24px;
}

/* === Buttons === */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 26px;
  border-radius: var(--radius-pill);
  font-weight: 600;
  font-size: 0.95rem;
  transition: all .2s ease;
  border: 1.5px solid transparent;
  cursor: pointer;
  white-space: nowrap;
}
.btn-primary {
  background: var(--forest);
  color: var(--white);
}
.btn-primary:hover { background: #1f2f1c; color: var(--white); transform: translateY(-1px); }
.btn-outline {
  background: transparent;
  color: var(--forest);
  border-color: var(--forest);
}
.btn-outline:hover { background: var(--forest); color: var(--white); }
.btn-green { background: var(--green); color: var(--white); }
.btn-green:hover { background: var(--green-dark); color: var(--white); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }

/* === Header === */
.site-header {
  position: sticky;
  top: 0;
  background: var(--white);
  border-bottom: 1px solid var(--border);
  z-index: 100;
  backdrop-filter: blur(10px);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 24px;
  max-width: 1320px;
  margin: 0 auto;
  gap: 24px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'Fraunces', serif;
  font-weight: 700;
  font-size: 1.3rem;
  color: var(--forest);
}
.logo-mark {
  width: 40px; height: 40px;
  background: var(--green);
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--white);
  font-size: 1.1rem;
}
.nav-primary {
  display: flex;
  gap: 4px;
  flex: 1;
  margin-left: 20px;
}
.nav-primary a {
  padding: 8px 14px;
  border-radius: var(--radius-pill);
  font-weight: 600;
  font-size: 0.92rem;
  color: var(--forest);
}
.nav-primary a:hover, .nav-primary a.active {
  background: var(--cream-light);
  color: var(--forest);
}
.nav-account { display: flex; gap: 8px; align-items: center; }
.icon-btn {
  width: 40px; height: 40px;
  border-radius: 50%;
  display: grid; place-items: center;
  color: var(--forest);
}
.icon-btn:hover { background: var(--cream-light); }

.menu-toggle { display: none; }

/* === Hero === */
.hero {
  background: linear-gradient(135deg, #00824A 0%, #006B3C 100%);
  color: var(--white);
  position: relative;
  overflow: hidden;
  padding: 80px 0 100px;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 80% 20%, rgba(243,206,161,0.25), transparent 50%),
              radial-gradient(circle at 20% 80%, rgba(50,70,47,0.4), transparent 50%);
}
.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 60px;
}
.hero h1 { color: var(--white); margin-bottom: 24px; }
.hero p { font-size: 1.15rem; margin-bottom: 32px; opacity: .92; max-width: 520px; }
.hero-image {
  height: 460px;
  border-radius: var(--radius-lg);
  background:
    linear-gradient(135deg, rgba(243,206,161,0.85), rgba(74,46,31,0.7)),
    radial-gradient(circle at 30% 30%, #f3cea1 0%, #c8956a 40%, #4a2e1f 100%);
  box-shadow: var(--shadow-lg);
  position: relative;
  overflow: hidden;
}
.hero-image::after {
  content: '☕';
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: 9rem;
  opacity: 0.4;
}
.hero .btn-primary { background: var(--white); color: var(--forest); }
.hero .btn-primary:hover { background: var(--cream); }

/* === Sections === */
section { padding: 70px 0; }
section.tight { padding: 50px 0; }

.section-title { text-align: center; margin-bottom: 14px; }
.section-subtitle { text-align: center; color: var(--text-muted); max-width: 680px; margin: 0 auto 50px; font-size: 1.05rem; }

/* === Promo cards === */
.promo-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
}
.promo-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 44px 40px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
  transition: transform .2s ease, box-shadow .2s ease;
}
.promo-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.promo-card.dark { background: var(--forest); color: var(--white); }
.promo-card.dark h2, .promo-card.dark h3 { color: var(--white); }
.promo-card.cream { background: var(--cream); border-color: transparent; }
.promo-card.green { background: var(--green); color: var(--white); }
.promo-card.green h2, .promo-card.green h3 { color: var(--white); }

.promo-card h2, .promo-card h3 { margin-bottom: 14px; }
.promo-card p { margin-bottom: 22px; }

.promo-image {
  height: 200px;
  border-radius: var(--radius-md);
  margin-bottom: 24px;
  background: linear-gradient(135deg, var(--cream), #d4a574);
}
.promo-image.citrus { background: linear-gradient(135deg, #ffd166, #ff9a3c); }
.promo-image.afternoon { background: linear-gradient(135deg, #6b4423, #c8956a); }
.promo-image.ai { background: linear-gradient(135deg, #32462f, #00824a); }
.promo-image.mango { background: linear-gradient(135deg, #ffb15c, #ff7a3d, #d84d2c); }
.promo-image.spring { background: linear-gradient(135deg, #c8a8d4, #8b6fa3, #5d4677); }
.promo-image.nondairy { background: linear-gradient(135deg, #faf3e8, #e8d4b0); }

.full-promo {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
}
.full-promo .promo-image { height: 100%; min-height: 320px; border-radius: 0; margin: 0; }
.full-promo .promo-text { padding: 56px 48px; display: flex; flex-direction: column; justify-content: center; }
.full-promo.flip .promo-image { order: 2; }

/* === Cookie banner === */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 24px;
  right: 24px;
  max-width: 540px;
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--border);
  padding: 24px 28px;
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.cookie-banner.hidden { display: none; }
.cookie-banner h4 { font-size: 1.1rem; color: var(--forest); }
.cookie-banner p { font-size: 0.92rem; color: var(--text-muted); }
.cookie-actions { display: flex; gap: 10px; flex-wrap: wrap; }

/* === Footer === */
.site-footer {
  background: var(--forest);
  color: #d8dcd5;
  padding: 70px 0 30px;
  margin-top: 80px;
}
.site-footer h4 {
  color: var(--white);
  font-family: 'Inter', sans-serif;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 20px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 40px;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 12px; }
.footer-col a {
  color: #b8c0b6;
  font-size: 0.92rem;
  transition: color .2s ease;
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  margin-top: 60px;
  padding-top: 28px;
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px;
  font-size: 0.85rem;
  color: #90998d;
}
.footer-toggle { display: none; }

/* === Breadcrumb === */
.breadcrumb {
  padding: 18px 0;
  font-size: 0.9rem;
  color: var(--text-muted);
}
.breadcrumb a { color: var(--text-muted); }
.breadcrumb a:hover { color: var(--green); }
.breadcrumb .sep { margin: 0 8px; }

/* === Menu page === */
.menu-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 60px;
  padding: 30px 0 60px;
}
.menu-sidebar h3 {
  font-family: 'Inter', sans-serif;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  margin: 26px 0 12px;
}
.menu-sidebar h3:first-child { margin-top: 0; }
.menu-sidebar ul { list-style: none; }
.menu-sidebar li { margin-bottom: 6px; }
.menu-sidebar a {
  display: block;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  color: var(--forest);
  font-weight: 500;
  font-size: 0.95rem;
  transition: background .15s ease;
}
.menu-sidebar a:hover, .menu-sidebar a.active {
  background: var(--cream-light);
  color: var(--green-dark);
}
.menu-section { margin-bottom: 60px; }
.menu-section h2 { margin-bottom: 6px; }
.menu-section .sub { color: var(--text-muted); margin-bottom: 30px; }
.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 28px;
}
.menu-item {
  cursor: pointer;
  transition: transform .2s ease;
}
.menu-item:hover { transform: translateY(-3px); }
.menu-item .thumb {
  height: 200px;
  border-radius: var(--radius-md);
  margin-bottom: 14px;
  background: linear-gradient(135deg, #f3cea1, #c8956a);
  box-shadow: var(--shadow-sm);
}
.menu-item .thumb.green { background: linear-gradient(135deg, #a8d4b0, #00824a); }
.menu-item .thumb.purple { background: linear-gradient(135deg, #c8a8d4, #5d4677); }
.menu-item .thumb.brown { background: linear-gradient(135deg, #c8956a, #4a2e1f); }
.menu-item .thumb.pink { background: linear-gradient(135deg, #ffc0c0, #d84d6f); }
.menu-item .thumb.yellow { background: linear-gradient(135deg, #ffe066, #ff9a3c); }
.menu-item .thumb.cream-bg { background: linear-gradient(135deg, #faf3e8, #f3cea1); }
.menu-item h4 {
  font-family: 'Inter', sans-serif;
  font-size: 1rem;
  color: var(--text);
  font-weight: 600;
}

/* === Rewards page === */
.rewards-hero {
  background: linear-gradient(135deg, #32462F 0%, #00824A 100%);
  color: var(--white);
  padding: 90px 0;
  text-align: center;
}
.rewards-hero h1 { color: var(--white); }
.rewards-hero p { font-size: 1.15rem; opacity: .9; max-width: 640px; margin: 20px auto 30px; }
.star { color: #FFD166; }

.steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.step-card {
  background: var(--white);
  padding: 36px 30px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  text-align: center;
}
.step-num {
  width: 48px; height: 48px;
  border-radius: 50%;
  background: var(--green);
  color: var(--white);
  font-weight: 700;
  display: grid; place-items: center;
  margin: 0 auto 18px;
  font-family: 'Fraunces', serif;
  font-size: 1.3rem;
}
.step-card h3 { margin-bottom: 10px; font-size: 1.2rem; }

.tiers {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.tier {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 36px 30px;
  border: 1px solid var(--border);
  position: relative;
  transition: transform .2s ease;
}
.tier:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.tier-badge {
  display: inline-block;
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 16px;
}
.tier.green .tier-badge { background: #d8f0e0; color: var(--green-dark); }
.tier.gold .tier-badge { background: #fcecc4; color: #8b6f1c; }
.tier.reserve .tier-badge { background: #2a1f1a; color: var(--cream); }
.tier.reserve { background: linear-gradient(135deg, #32462f, #1a2618); color: #d8dcd5; border-color: transparent; }
.tier.reserve h3 { color: var(--white); }
.tier h3 { font-size: 1.4rem; margin-bottom: 6px; }
.tier .threshold { font-size: 0.95rem; color: var(--text-muted); margin-bottom: 22px; }
.tier.reserve .threshold { color: #b8c0b6; }
.tier ul { list-style: none; }
.tier li { padding: 10px 0; border-top: 1px solid var(--border); font-size: 0.95rem; }
.tier.reserve li { border-color: rgba(255,255,255,0.1); }
.tier li::before { content: '★ '; color: var(--green); font-size: 0.9em; }
.tier.reserve li::before { color: var(--cream); }

/* Rewards tabs */
.tabs {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  border: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
}
.tab-list {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  border-bottom: 1px solid var(--border);
  padding-bottom: 24px;
  margin-bottom: 30px;
}
.tab-btn {
  padding: 10px 20px;
  border-radius: var(--radius-pill);
  background: var(--cream-light);
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--forest);
  border: 2px solid transparent;
  transition: all .2s ease;
}
.tab-btn:hover { background: var(--cream); }
.tab-btn.active {
  background: var(--green);
  color: var(--white);
  border-color: var(--green);
}
.tab-panel { display: none; }
.tab-panel.active {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
  animation: fade .3s ease;
}
@keyframes fade { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
.tab-panel .panel-img {
  height: 240px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--cream), var(--coffee-warm));
}
.tab-panel h3 { font-size: 1.5rem; margin-bottom: 10px; }
.tab-panel .value-tag {
  display: inline-block;
  background: var(--cream-light);
  color: var(--forest);
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  font-size: 0.85rem;
  font-weight: 700;
  margin-top: 14px;
}

.partnerships {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.partner-card {
  background: var(--white);
  padding: 36px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  display: flex;
  gap: 24px;
  align-items: center;
}
.partner-logo {
  width: 76px; height: 76px;
  border-radius: 50%;
  background: var(--cream-light);
  display: grid; place-items: center;
  font-size: 1.6rem;
  flex-shrink: 0;
  color: var(--forest);
  font-weight: 700;
}

/* === Gift cards === */
.gift-hero {
  background: linear-gradient(135deg, var(--cream), #e8b88a);
  padding: 70px 0;
}
.gift-hero-inner { display: grid; grid-template-columns: 1.2fr 1fr; gap: 50px; align-items: center; }
.gift-hero h1 { color: var(--coffee); }
.gift-hero p { font-size: 1.1rem; margin: 18px 0 28px; color: var(--coffee-warm); }
.gift-stack {
  position: relative;
  height: 320px;
}
.gift-card-design {
  position: absolute;
  width: 230px;
  height: 150px;
  border-radius: 14px;
  box-shadow: var(--shadow-md);
  display: grid;
  place-items: center;
  color: var(--white);
  font-family: 'Fraunces', serif;
  font-size: 1.15rem;
  text-align: center;
  padding: 10px;
}
.gift-stack .gift-card-design:nth-child(1) { background: linear-gradient(135deg, #00824A, #006B3C); top: 10px; left: 0; transform: rotate(-8deg); }
.gift-stack .gift-card-design:nth-child(2) { background: linear-gradient(135deg, #d84d6f, #a32a4d); top: 60px; left: 100px; transform: rotate(2deg); }
.gift-stack .gift-card-design:nth-child(3) { background: linear-gradient(135deg, #4a2e1f, #6b4423); top: 130px; left: 30px; transform: rotate(-3deg); }

.carousel { position: relative; padding: 0 60px; }
.carousel-track {
  display: flex;
  gap: 22px;
  overflow: hidden;
  scroll-behavior: smooth;
}
.carousel-card {
  flex: 0 0 calc((100% - 66px) / 4);
  min-width: 0;
}
.gift-thumb {
  aspect-ratio: 1.6 / 1;
  border-radius: var(--radius-md);
  display: grid;
  place-items: center;
  color: var(--white);
  font-family: 'Fraunces', serif;
  font-size: 1.1rem;
  text-align: center;
  padding: 16px;
  box-shadow: var(--shadow-sm);
  transition: transform .2s ease, box-shadow .2s ease;
  cursor: pointer;
}
.gift-thumb:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.carousel-card p {
  text-align: center;
  margin-top: 10px;
  font-size: 0.9rem;
  color: var(--text-muted);
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px; height: 44px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: var(--shadow-md);
  display: grid;
  place-items: center;
  color: var(--forest);
  font-size: 1.2rem;
  z-index: 5;
  border: 1px solid var(--border);
  transition: background .2s ease;
}
.carousel-btn:hover { background: var(--cream-light); }
.carousel-btn:disabled { opacity: 0.4; cursor: not-allowed; }
.carousel-btn.prev { left: 0; }
.carousel-btn.next { right: 0; }

.category-section { margin-bottom: 70px; }
.category-section h3 {
  font-family: 'Fraunces', serif;
  font-size: 1.6rem;
  margin-bottom: 22px;
}

/* Color palette for gift card thumbs */
.gc-1 { background: linear-gradient(135deg, #00824A, #006B3C); }
.gc-2 { background: linear-gradient(135deg, #f3cea1, #c8956a); color: #4a2e1f !important; }
.gc-3 { background: linear-gradient(135deg, #d84d6f, #8b1f3f); }
.gc-4 { background: linear-gradient(135deg, #5d4677, #32264a); }
.gc-5 { background: linear-gradient(135deg, #ffd166, #ff9a3c); color: #4a2e1f !important; }
.gc-6 { background: linear-gradient(135deg, #4a2e1f, #2a1810); }
.gc-7 { background: linear-gradient(135deg, #00824A, #32462F); }
.gc-8 { background: linear-gradient(135deg, #c8a8d4, #8b6fa3); }
.gc-9 { background: linear-gradient(135deg, #ff7a9c, #d84d6f); }
.gc-10 { background: linear-gradient(135deg, #6b4423, #4a2e1f); }
.gc-11 { background: linear-gradient(135deg, #32462F, #1a2618); }
.gc-12 { background: linear-gradient(135deg, #00824A, #f3cea1); }

.business-gifting {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 50px;
  align-items: center;
  background: var(--forest);
  color: var(--white);
  border-radius: var(--radius-lg);
  padding: 56px;
}
.business-gifting h2 { color: var(--white); }
.business-gifting p { margin: 18px 0 26px; opacity: 0.92; }
.business-image {
  height: 280px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--cream), var(--coffee-warm));
}

.egift-info { background: var(--cream-light); }
.egift-grid { display: grid; grid-template-columns: 1.2fr 1fr; gap: 50px; align-items: center; }

.faq-item {
  background: var(--white);
  border-radius: var(--radius-md);
  padding: 24px 28px;
  margin-bottom: 14px;
  border: 1px solid var(--border);
}
.faq-item summary {
  font-weight: 600;
  font-size: 1.05rem;
  cursor: pointer;
  list-style: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--forest);
}
.faq-item summary::after { content: '+'; font-size: 1.4rem; color: var(--green); transition: transform .2s; }
.faq-item[open] summary::after { transform: rotate(45deg); }
.faq-item p { padding-top: 14px; color: var(--text-muted); }

/* === Store locator === */
.locator-controls {
  background: var(--white);
  border-bottom: 1px solid var(--border);
  padding: 24px 0;
}
.controls-inner {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  align-items: center;
}
.toggle-group {
  display: inline-flex;
  background: var(--cream-light);
  border-radius: var(--radius-pill);
  padding: 4px;
  gap: 2px;
}
.toggle-btn {
  padding: 8px 22px;
  border-radius: var(--radius-pill);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--forest);
  transition: all .2s ease;
}
.toggle-btn.active { background: var(--white); box-shadow: var(--shadow-sm); color: var(--green-dark); }

.search-box {
  flex: 1;
  min-width: 280px;
  position: relative;
}
.search-input {
  width: 100%;
  padding: 14px 20px 14px 48px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-pill);
  font-family: inherit;
  font-size: 0.95rem;
  background: var(--bg);
  transition: border-color .2s ease;
}
.search-input:focus {
  outline: none;
  border-color: var(--green);
  background: var(--white);
}
.search-icon {
  position: absolute;
  left: 18px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
}
.suggestions {
  position: absolute;
  top: calc(100% + 6px);
  left: 0; right: 0;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  z-index: 10;
  display: none;
  overflow: hidden;
}
.suggestions.show { display: block; }
.suggestion {
  padding: 12px 18px;
  cursor: pointer;
  border-bottom: 1px solid var(--border);
  font-size: 0.92rem;
}
.suggestion:last-child { border: none; }
.suggestion:hover { background: var(--cream-light); }

.filter-btn {
  padding: 12px 22px;
  border-radius: var(--radius-pill);
  border: 1.5px solid var(--border);
  background: var(--white);
  color: var(--forest);
  font-weight: 600;
  font-size: 0.92rem;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.filter-btn:hover, .filter-btn.active { border-color: var(--green); color: var(--green-dark); }

.filter-panel {
  display: none;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 24px;
  margin-top: 16px;
  box-shadow: var(--shadow-sm);
}
.filter-panel.show { display: block; }
.filter-group h4 { font-family: 'Inter', sans-serif; font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-muted); margin-bottom: 12px; }
.filter-options { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 18px; }
.filter-chip {
  padding: 8px 14px;
  border-radius: var(--radius-pill);
  background: var(--cream-light);
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--forest);
  cursor: pointer;
  border: 1.5px solid transparent;
  transition: all .15s ease;
}
.filter-chip:hover { background: var(--cream); }
.filter-chip.active { background: var(--green); color: var(--white); border-color: var(--green); }

.locator-layout {
  display: grid;
  grid-template-columns: 420px 1fr;
  height: calc(100vh - 200px);
  min-height: 600px;
}
.results-list {
  overflow-y: auto;
  padding: 24px;
  background: var(--white);
  border-right: 1px solid var(--border);
}
.results-count {
  font-size: 0.88rem;
  color: var(--text-muted);
  margin-bottom: 16px;
}
.store-card {
  padding: 20px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  margin-bottom: 14px;
  cursor: pointer;
  transition: all .2s ease;
}
.store-card:hover { border-color: var(--green); box-shadow: var(--shadow-sm); }
.store-card h4 { font-family: 'Inter', sans-serif; font-size: 1rem; margin-bottom: 6px; color: var(--forest); }
.store-card .addr { color: var(--text-muted); font-size: 0.9rem; margin-bottom: 8px; }
.store-card .hours { color: var(--green); font-weight: 600; font-size: 0.85rem; margin-bottom: 10px; }
.store-card .features { display: flex; gap: 6px; flex-wrap: wrap; }
.store-card .feature {
  background: var(--cream-light);
  color: var(--forest);
  padding: 3px 10px;
  border-radius: var(--radius-pill);
  font-size: 0.75rem;
  font-weight: 600;
}

.map-view {
  background:
    radial-gradient(circle at 30% 40%, rgba(0,130,74,0.08), transparent 30%),
    radial-gradient(circle at 70% 60%, rgba(0,130,74,0.06), transparent 30%),
    linear-gradient(135deg, #eaf2e8 0%, #d8e6d2 100%);
  position: relative;
  overflow: hidden;
}
.map-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(50,70,47,0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(50,70,47,0.06) 1px, transparent 1px);
  background-size: 40px 40px;
}
.map-pin {
  position: absolute;
  width: 36px; height: 36px;
  background: var(--green);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  box-shadow: var(--shadow-md);
  display: grid;
  place-items: center;
  color: var(--white);
  cursor: pointer;
}
.map-pin::after {
  content: '☕';
  transform: rotate(45deg);
  font-size: 1rem;
}
.map-pin:hover { background: var(--green-dark); transform: rotate(-45deg) scale(1.1); }

/* === Responsive === */
@media (max-width: 960px) {
  .nav-primary { display: none; }
  .menu-toggle { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; color: var(--forest); }
  .menu-toggle:hover { background: var(--cream-light); }
  .hero { padding: 60px 0 70px; }
  .hero-inner { grid-template-columns: 1fr; }
  .hero-image { height: 280px; }
  .promo-grid, .full-promo, .gift-hero-inner, .egift-grid, .business-gifting, .partnerships, .tab-panel.active { grid-template-columns: 1fr; }
  .full-promo .promo-text { padding: 36px 28px; }
  .full-promo .promo-image { min-height: 220px; }
  .menu-layout { grid-template-columns: 1fr; gap: 30px; }
  .menu-sidebar { background: var(--white); padding: 24px; border-radius: var(--radius-md); border: 1px solid var(--border); }
  .steps, .tiers { grid-template-columns: 1fr; }
  .business-gifting { padding: 36px 28px; }
  .carousel-card { flex: 0 0 calc((100% - 22px) / 2); }
  .locator-layout { grid-template-columns: 1fr; height: auto; }
  .map-view { height: 400px; }
  .results-list { border-right: none; border-bottom: 1px solid var(--border); }

  /* Footer accordion */
  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col {
    border-bottom: 1px solid rgba(255,255,255,0.1);
  }
  .footer-col h4 {
    margin: 0;
    padding: 18px 0;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .footer-toggle { display: inline; transition: transform .2s ease; font-size: 1.4rem; font-weight: 400; }
  .footer-col.expanded .footer-toggle { transform: rotate(45deg); }
  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height .3s ease, padding .3s ease;
    padding-bottom: 0;
  }
  .footer-col.expanded ul {
    max-height: 600px;
    padding-bottom: 18px;
  }
}

@media (max-width: 600px) {
  .container { padding: 0 16px; }
  section { padding: 50px 0; }
  .carousel { padding: 0 44px; }
  .carousel-card { flex: 0 0 100%; }
  .tab-list { gap: 6px; }
  .tab-btn { padding: 8px 14px; font-size: 0.85rem; }
  .gift-stack { height: 260px; }
  .gift-card-design { width: 180px; height: 120px; font-size: 0.95rem; }
}

raw_arguments.content:
/* GreenBean Coffee — shared styles */
:root {
  --green: #00824A;
  --green-dark: #006B3C;
  --forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FAF3E8;
  --coffee: #4A2E1F;
  --coffee-warm: #6B4423;
  --bg: #FCFAF6;
  --text: #1E2A24;
  --text-muted: #5A6760;
  --border: #E5DFD3;
  --white: #FFFFFF;
  --shadow-sm: 0 2px 8px rgba(50, 70, 47, 0.06);
  --shadow-md: 0 6px 20px rgba(50, 70, 47, 0.10);
  --shadow-lg: 0 12px 40px rgba(50, 70, 47, 0.14);
  --radius-sm: 10px;
  --radius-md: 18px;
  --radius-lg: 28px;
  --radius-pill: 999px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4 {
  font-family: 'Fraunces', 'Playfair Display', Georgia, serif;
  font-weight: 600;
  line-height: 1.15;
  color: var(--forest);
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.4rem, 5vw, 4rem); }
h2 { font-size: clamp(1.8rem, 3.5vw, 2.6rem); }
h3 { font-size: clamp(1.3rem, 2vw, 1.6rem); }

a { color: var(--green); text-decoration: none; transition: color .2s ease; }
a:hover { color: var(--green-dark); }

img { max-width: 100%; display: block; }

button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 24px;
}

/* === Buttons === */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 26px;
  border-radius: var(--radius-pill);
  font-weight: 600;
  font-size: 0.95rem;
  transition: all .2s ease;
  border: 1.5px solid transparent;
  cursor: pointer;
  white-space: nowrap;
}
.btn-primary {
  background: var(--forest);
  color: var(--white);
}
.btn-primary:hover { background: #1f2f1c; color: var(--white); transform: translateY(-1px); }
.btn-outline {
  background: transparent;
  color: var(--forest);
  border-color: var(--forest);
}
.btn-outline:hover { background: var(--forest); color: var(--white); }
.btn-green { background: var(--green); color: var(--white); }
.btn-green:hover { background: var(--green-dark); color: var(--white); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }

/* === Header === */
.site-header {
  position: sticky;
  top: 0;
  background: var(--white);
  border-bottom: 1px solid var(--border);
  z-index: 100;
  backdrop-filter: blur(10px);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 24px;
  max-width: 1320px;
  margin: 0 auto;
  gap: 24px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'Fraunces', serif;
  font-weight: 700;
  font-size: 1.3rem;
  color: var(--forest);
}
.logo-mark {
  width: 40px; height: 40px;
  background: var(--green);
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--white);
  font-size: 1.1rem;
}
.nav-primary {
  display: flex;
  gap: 4px;
  flex: 1;
  margin-left: 20px;
}
.nav-primary a {
  padding: 8px 14px;
  border-radius: var(--radius-pill);
  font-weight: 600;
  font-size: 0.92rem;
  color: var(--forest);
}
.nav-primary a:hover, .nav-primary a.active {
  background: var(--cream-light);
  color: var(--forest);
}
.nav-account { display: flex; gap: 8px; align-items: center; }
.icon-btn {
  width: 40px; height: 40px;
  border-radius: 50%;
  display: grid; place-items: center;
  color: var(--forest);
}
.icon-btn:hover { background: var(--cream-light); }

.menu-toggle { display: none; }

/* === Hero === */
.hero {
  background: linear-gradient(135deg, #00824A 0%, #006B3C 100%);
  color: var(--white);
  position: relative;
  overflow: hidden;
  padding: 80px 0 100px;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 80% 20%, rgba(243,206,161,0.25), transparent 50%),
              radial-gradient(circle at 20% 80%, rgba(50,70,47,0.4), transparent 50%);
}
.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 60px;
}
.hero h1 { color: var(--white); margin-bottom: 24px; }
.hero p { font-size: 1.15rem; margin-bottom: 32px; opacity: .92; max-width: 520px; }
.hero-image {
  height: 460px;
  border-radius: var(--radius-lg);
  background:
    linear-gradient(135deg, rgba(243,206,161,0.85), rgba(74,46,31,0.7)),
    radial-gradient(circle at 30% 30%, #f3cea1 0%, #c8956a 40%, #4a2e1f 100%);
  box-shadow: var(--shadow-lg);
  position: relative;
  overflow: hidden;
}
.hero-image::after {
  content: '☕';
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: 9rem;
  opacity: 0.4;
}
.hero .btn-primary { background: var(--white); color: var(--forest); }
.hero .btn-primary:hover { background: var(--cream); }

/* === Sections === */
section { padding: 70px 0; }
section.tight { padding: 50px 0; }

.section-title { text-align: center; margin-bottom: 14px; }
.section-subtitle { text-align: center; color: var(--text-muted); max-width: 680px; margin: 0 auto 50px; font-size: 1.05rem; }

/* === Promo cards === */
.promo-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
}
.promo-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 44px 40px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
  transition: transform .2s ease, box-shadow .2s ease;
}
.promo-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.promo-card.dark { background: var(--forest); color: var(--white); }
.promo-card.dark h2, .promo-card.dark h3 { color: var(--white); }
.promo-card.cream { background: var(--cream); border-color: transparent; }
.promo-card.green { background: var(--green); color: var(--white); }
.promo-card.green h2, .promo-card.green h3 { color: var(--white); }

.promo-card h2, .promo-card h3 { margin-bottom: 14px; }
.promo-card p { margin-bottom: 22px; }

.promo-image {
  height: 200px;
  border-radius: var(--radius-md);
  margin-bottom: 24px;
  background: linear-gradient(135deg, var(--cream), #d4a574);
}
.promo-image.citrus { background: linear-gradient(135deg, #ffd166, #ff9a3c); }
.promo-image.afternoon { background: linear-gradient(135deg, #6b4423, #c8956a); }
.promo-image.ai { background: linear-gradient(135deg, #32462f, #00824a); }
.promo-image.mango { background: linear-gradient(135deg, #ffb15c, #ff7a3d, #d84d2c); }
.promo-image.spring { background: linear-gradient(135deg, #c8a8d4, #8b6fa3, #5d4677); }
.promo-image.nondairy { background: linear-gradient(135deg, #faf3e8, #e8d4b0); }

.full-promo {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
}
.full-promo .promo-image { height: 100%; min-height: 320px; border-radius: 0; margin: 0; }
.full-promo .promo-text { padding: 56px 48px; display: flex; flex-direction: column; justify-content: center; }
.full-promo.flip .promo-image { order: 2; }

/* === Cookie banner === */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 24px;
  right: 24px;
  max-width: 540px;
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--border);
  padding: 24px 28px;
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.cookie-banner.hidden { display: none; }
.cookie-banner h4 { font-size: 1.1rem; color: var(--forest); }
.cookie-banner p { font-size: 0.92rem; color: var(--text-muted); }
.cookie-actions { display: flex; gap: 10px; flex-wrap: wrap; }

/* === Footer === */
.site-footer {
  background: var(--forest);
  color: #d8dcd5;
  padding: 70px 0 30px;
  margin-top: 80px;
}
.site-footer h4 {
  color: var(--white);
  font-family: 'Inter', sans-serif;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 20px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 40px;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 12px; }
.footer-col a {
  color: #b8c0b6;
  font-size: 0.92rem;
  transition: color .2s ease;
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  margin-top: 60px;
  padding-top: 28px;
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px;
  font-size: 0.85rem;
  color: #90998d;
}
.footer-toggle { display: none; }

/* === Breadcrumb === */
.breadcrumb {
  padding: 18px 0;
  font-size: 0.9rem;
  color: var(--text-muted);
}
.breadcrumb a { color: var(--text-muted); }
.breadcrumb a:hover { color: var(--green); }
.breadcrumb .sep { margin: 0 8px; }

/* === Menu page === */
.menu-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 60px;
  padding: 30px 0 60px;
}
.menu-sidebar h3 {
  font-family: 'Inter', sans-serif;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  margin: 26px 0 12px;
}
.menu-sidebar h3:first-child { margin-top: 0; }
.menu-sidebar ul { list-style: none; }
.menu-sidebar li { margin-bottom: 6px; }
.menu-sidebar a {
  display: block;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  color: var(--forest);
  font-weight: 500;
  font-size: 0.95rem;
  transition: background .15s ease;
}
.menu-sidebar a:hover, .menu-sidebar a.active {
  background: var(--cream-light);
  color: var(--green-dark);
}
.menu-section { margin-bottom: 60px; }
.menu-section h2 { margin-bottom: 6px; }
.menu-section .sub { color: var(--text-muted); margin-bottom: 30px; }
.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 28px;
}
.menu-item {
  cursor: pointer;
  transition: transform .2s ease;
}
.menu-item:hover { transform: translateY(-3px); }
.menu-item .thumb {
  height: 200px;
  border-radius: var(--radius-md);
  margin-bottom: 14px;
  background: linear-gradient(135deg, #f3cea1, #c8956a);
  box-shadow: var(--shadow-sm);
}
.menu-item .thumb.green { background: linear-gradient(135deg, #a8d4b0, #00824a); }
.menu-item .thumb.purple { background: linear-gradient(135deg, #c8a8d4, #5d4677); }
.menu-item .thumb.brown { background: linear-gradient(135deg, #c8956a, #4a2e1f); }
.menu-item .thumb.pink { background: linear-gradient(135deg, #ffc0c0, #d84d6f); }
.menu-item .thumb.yellow { background: linear-gradient(135deg, #ffe066, #ff9a3c); }
.menu-item .thumb.cream-bg { background: linear-gradient(135deg, #faf3e8, #f3cea1); }
.menu-item h4 {
  font-family: 'Inter', sans-serif;
  font-size: 1rem;
  color: var(--text);
  font-weight: 600;
}

/* === Rewards page === */
.rewards-hero {
  background: linear-gradient(135deg, #32462F 0%, #00824A 100%);
  color: var(--white);
  padding: 90px 0;
  text-align: center;
}
.rewards-hero h1 { color: var(--white); }
.rewards-hero p { font-size: 1.15rem; opacity: .9; max-width: 640px; margin: 20px auto 30px; }
.star { color: #FFD166; }

.steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.step-card {
  background: var(--white);
  padding: 36px 30px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  text-align: center;
}
.step-num {
  width: 48px; height: 48px;
  border-radius: 50%;
  background: var(--green);
  color: var(--white);
  font-weight: 700;
  display: grid; place-items: center;
  margin: 0 auto 18px;
  font-family: 'Fraunces', serif;
  font-size: 1.3rem;
}
.step-card h3 { margin-bottom: 10px; font-size: 1.2rem; }

.tiers {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.tier {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 36px 30px;
  border: 1px solid var(--border);
  position: relative;
  transition: transform .2s ease;
}
.tier:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.tier-badge {
  display: inline-block;
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 16px;
}
.tier.green .tier-badge { background: #d8f0e0; color: var(--green-dark); }
.tier.gold .tier-badge { background: #fcecc4; color: #8b6f1c; }
.tier.reserve .tier-badge { background: #2a1f1a; color: var(--cream); }
.tier.reserve { background: linear-gradient(135deg, #32462f, #1a2618); color: #d8dcd5; border-color: transparent; }
.tier.reserve h3 { color: var(--white); }
.tier h3 { font-size: 1.4rem; margin-bottom: 6px; }
.tier .threshold { font-size: 0.95rem; color: var(--text-muted); margin-bottom: 22px; }
.tier.reserve .threshold { color: #b8c0b6; }
.tier ul { list-style: none; }
.tier li { padding: 10px 0; border-top: 1px solid var(--border); font-size: 0.95rem; }
.tier.reserve li { border-color: rgba(255,255,255,0.1); }
.tier li::before { content: '★ '; color: var(--green); font-size: 0.9em; }
.tier.reserve li::before { color: var(--cream); }

/* Rewards tabs */
.tabs {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  border: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
}
.tab-list {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  border-bottom: 1px solid var(--border);
  padding-bottom: 24px;
  margin-bottom: 30px;
}
.tab-btn {
  padding: 10px 20px;
  border-radius: var(--radius-pill);
  background: var(--cream-light);
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--forest);
  border: 2px solid transparent;
  transition: all .2s ease;
}
.tab-btn:hover { background: var(--cream); }
.tab-btn.active {
  background: var(--green);
  color: var(--white);
  border-color: var(--green);
}
.tab-panel { display: none; }
.tab-panel.active {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
  animation: fade .3s ease;
}
@keyframes fade { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
.tab-panel .panel-img {
  height: 240px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--cream), var(--coffee-warm));
}
.tab-panel h3 { font-size: 1.5rem; margin-bottom: 10px; }
.tab-panel .value-tag {
  display: inline-block;
  background: var(--cream-light);
  color: var(--forest);
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  font-size: 0.85rem;
  font-weight: 700;
  margin-top: 14px;
}

.partnerships {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.partner-card {
  background: var(--white);
  padding: 36px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  display: flex;
  gap: 24px;
  align-items: center;
}
.partner-logo {
  width: 76px; height: 76px;
  border-radius: 50%;
  background: var(--cream-light);
  display: grid; place-items: center;
  font-size: 1.6rem;
  flex-shrink: 0;
  color: var(--forest);
  font-weight: 700;
}

/* === Gift cards === */
.gift-hero {
  background: linear-gradient(135deg, var(--cream), #e8b88a);
  padding: 70px 0;
}
.gift-hero-inner { display: grid; grid-template-columns: 1.2fr 1fr; gap: 50px; align-items: center; }
.gift-hero h1 { color: var(--coffee); }
.gift-hero p { font-size: 1.1rem; margin: 18px 0 28px; color: var(--coffee-warm); }
.gift-stack {
  position: relative;
  height: 320px;
}
.gift-card-design {
  position: absolute;
  width: 230px;
  height: 150px;
  border-radius: 14px;
  box-shadow: var(--shadow-md);
  display: grid;
  place-items: center;
  color: var(--white);
  font-family: 'Fraunces', serif;
  font-size: 1.15rem;
  text-align: center;
  padding: 10px;
}
.gift-stack .gift-card-design:nth-child(1) { background: linear-gradient(135deg, #00824A, #006B3C); top: 10px; left: 0; transform: rotate(-8deg); }
.gift-stack .gift-card-design:nth-child(2) { background: linear-gradient(135deg, #d84d6f, #a32a4d); top: 60px; left: 100px; transform: rotate(2deg); }
.gift-stack .gift-card-design:nth-child(3) { background: linear-gradient(135deg, #4a2e1f, #6b4423); top: 130px; left: 30px; transform: rotate(-3deg); }

.carousel { position: relative; padding: 0 60px; }
.carousel-track {
  display: flex;
  gap: 22px;
  overflow: hidden;
  scroll-behavior: smooth;
}
.carousel-card {
  flex: 0 0 calc((100% - 66px) / 4);
  min-width: 0;
}
.gift-thumb {
  aspect-ratio: 1.6 / 1;
  border-radius: var(--radius-md);
  display: grid;
  place-items: center;
  color: var(--white);
  font-family: 'Fraunces', serif;
  font-size: 1.1rem;
  text-align: center;
  padding: 16px;
  box-shadow: var(--shadow-sm);
  transition: transform .2s ease, box-shadow .2s ease;
  cursor: pointer;
}
.gift-thumb:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.carousel-card p {
  text-align: center;
  margin-top: 10px;
  font-size: 0.9rem;
  color: var(--text-muted);
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px; height: 44px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: var(--shadow-md);
  display: grid;
  place-items: center;
  color: var(--forest);
  font-size: 1.2rem;
  z-index: 5;
  border: 1px solid var(--border);
  transition: background .2s ease;
}
.carousel-btn:hover { background: var(--cream-light); }
.carousel-btn:disabled { opacity: 0.4; cursor: not-allowed; }
.carousel-btn.prev { left: 0; }
.carousel-btn.next { right: 0; }

.category-section { margin-bottom: 70px; }
.category-section h3 {
  font-family: 'Fraunces', serif;
  font-size: 1.6rem;
  margin-bottom: 22px;
}

/* Color palette for gift card thumbs */
.gc-1 { background: linear-gradient(135deg, #00824A, #006B3C); }
.gc-2 { background: linear-gradient(135deg, #f3cea1, #c8956a); color: #4a2e1f !important; }
.gc-3 { background: linear-gradient(135deg, #d84d6f, #8b1f3f); }
.gc-4 { background: linear-gradient(135deg, #5d4677, #32264a); }
.gc-5 { background: linear-gradient(135deg, #ffd166, #ff9a3c); color: #4a2e1f !important; }
.gc-6 { background: linear-gradient(135deg, #4a2e1f, #2a1810); }
.gc-7 { background: linear-gradient(135deg, #00824A, #32462F); }
.gc-8 { background: linear-gradient(135deg, #c8a8d4, #8b6fa3); }
.gc-9 { background: linear-gradient(135deg, #ff7a9c, #d84d6f); }
.gc-10 { background: linear-gradient(135deg, #6b4423, #4a2e1f); }
.gc-11 { background: linear-gradient(135deg, #32462F, #1a2618); }
.gc-12 { background: linear-gradient(135deg, #00824A, #f3cea1); }

.business-gifting {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 50px;
  align-items: center;
  background: var(--forest);
  color: var(--white);
  border-radius: var(--radius-lg);
  padding: 56px;
}
.business-gifting h2 { color: var(--white); }
.business-gifting p { margin: 18px 0 26px; opacity: 0.92; }
.business-image {
  height: 280px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--cream), var(--coffee-warm));
}

.egift-info { background: var(--cream-light); }
.egift-grid { display: grid; grid-template-columns: 1.2fr 1fr; gap: 50px; align-items: center; }

.faq-item {
  background: var(--white);
  border-radius: var(--radius-md);
  padding: 24px 28px;
  margin-bottom: 14px;
  border: 1px solid var(--border);
}
.faq-item summary {
  font-weight: 600;
  font-size: 1.05rem;
  cursor: pointer;
  list-style: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--forest);
}
.faq-item summary::after { content: '+'; font-size: 1.4rem; color: var(--green); transition: transform .2s; }
.faq-item[open] summary::after { transform: rotate(45deg); }
.faq-item p { padding-top: 14px; color: var(--text-muted); }

/* === Store locator === */
.locator-controls {
  background: var(--white);
  border-bottom: 1px solid var(--border);
  padding: 24px 0;
}
.controls-inner {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  align-items: center;
}
.toggle-group {
  display: inline-flex;
  background: var(--cream-light);
  border-radius: var(--radius-pill);
  padding: 4px;
  gap: 2px;
}
.toggle-btn {
  padding: 8px 22px;
  border-radius: var(--radius-pill);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--forest);
  transition: all .2s ease;
}
.toggle-btn.active { background: var(--white); box-shadow: var(--shadow-sm); color: var(--green-dark); }

.search-box {
  flex: 1;
  min-width: 280px;
  position: relative;
}
.search-input {
  width: 100%;
  padding: 14px 20px 14px 48px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-pill);
  font-family: inherit;
  font-size: 0.95rem;
  background: var(--bg);
  transition: border-color .2s ease;
}
.search-input:focus {
  outline: none;
  border-color: var(--green);
  background: var(--white);
}
.search-icon {
  position: absolute;
  left: 18px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
}
.suggestions {
  position: absolute;
  top: calc(100% + 6px);
  left: 0; right: 0;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  z-index: 10;
  display: none;
  overflow: hidden;
}
.suggestions.show { display: block; }
.suggestion {
  padding: 12px 18px;
  cursor: pointer;
  border-bottom: 1px solid var(--border);
  font-size: 0.92rem;
}
.suggestion:last-child { border: none; }
.suggestion:hover { background: var(--cream-light); }

.filter-btn {
  padding: 12px 22px;
  border-radius: var(--radius-pill);
  border: 1.5px solid var(--border);
  background: var(--white);
  color: var(--forest);
  font-weight: 600;
  font-size: 0.92rem;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.filter-btn:hover, .filter-btn.active { border-color: var(--green); color: var(--green-dark); }

.filter-panel {
  display: none;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 24px;
  margin-top: 16px;
  box-shadow: var(--shadow-sm);
}
.filter-panel.show { display: block; }
.filter-group h4 { font-family: 'Inter', sans-serif; font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-muted); margin-bottom: 12px; }
.filter-options { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 18px; }
.filter-chip {
  padding: 8px 14px;
  border-radius: var(--radius-pill);
  background: var(--cream-light);
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--forest);
  cursor: pointer;
  border: 1.5px solid transparent;
  transition: all .15s ease;
}
.filter-chip:hover { background: var(--cream); }
.filter-chip.active { background: var(--green); color: var(--white); border-color: var(--green); }

.locator-layout {
  display: grid;
  grid-template-columns: 420px 1fr;
  height: calc(100vh - 200px);
  min-height: 600px;
}
.results-list {
  overflow-y: auto;
  padding: 24px;
  background: var(--white);
  border-right: 1px solid var(--border);
}
.results-count {
  font-size: 0.88rem;
  color: var(--text-muted);
  margin-bottom: 16px;
}
.store-card {
  padding: 20px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  margin-bottom: 14px;
  cursor: pointer;
  transition: all .2s ease;
}
.store-card:hover { border-color: var(--green); box-shadow: var(--shadow-sm); }
.store-card h4 { font-family: 'Inter', sans-serif; font-size: 1rem; margin-bottom: 6px; color: var(--forest); }
.store-card .addr { color: var(--text-muted); font-size: 0.9rem; margin-bottom: 8px; }
.store-card .hours { color: var(--green); font-weight: 600; font-size: 0.85rem; margin-bottom: 10px; }
.store-card .features { display: flex; gap: 6px; flex-wrap: wrap; }
.store-card .feature {
  background: var(--cream-light);
  color: var(--forest);
  padding: 3px 10px;
  border-radius: var(--radius-pill);
  font-size: 0.75rem;
  font-weight: 600;
}

.map-view {
  background:
    radial-gradient(circle at 30% 40%, rgba(0,130,74,0.08), transparent 30%),
    radial-gradient(circle at 70% 60%, rgba(0,130,74,0.06), transparent 30%),
    linear-gradient(135deg, #eaf2e8 0%, #d8e6d2 100%);
  position: relative;
  overflow: hidden;
}
.map-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(50,70,47,0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(50,70,47,0.06) 1px, transparent 1px);
  background-size: 40px 40px;
}
.map-pin {
  position: absolute;
  width: 36px; height: 36px;
  background: var(--green);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  box-shadow: var(--shadow-md);
  display: grid;
  place-items: center;
  color: var(--white);
  cursor: pointer;
}
.map-pin::after {
  content: '☕';
  transform: rotate(45deg);
  font-size: 1rem;
}
.map-pin:hover { background: var(--green-dark); transform: rotate(-45deg) scale(1.1); }

/* === Responsive === */
@media (max-width: 960px) {
  .nav-primary { display: none; }
  .menu-toggle { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; color: var(--forest); }
  .menu-toggle:hover { background: var(--cream-light); }
  .hero { padding: 60px 0 70px; }
  .hero-inner { grid-template-columns: 1fr; }
  .hero-image { height: 280px; }
  .promo-grid, .full-promo, .gift-hero-inner, .egift-grid, .business-gifting, .partnerships, .tab-panel.active { grid-template-columns: 1fr; }
  .full-promo .promo-text { padding: 36px 28px; }
  .full-promo .promo-image { min-height: 220px; }
  .menu-layout { grid-template-columns: 1fr; gap: 30px; }
  .menu-sidebar { background: var(--white); padding: 24px; border-radius: var(--radius-md); border: 1px solid var(--border); }
  .steps, .tiers { grid-template-columns: 1fr; }
  .business-gifting { padding: 36px 28px; }
  .carousel-card { flex: 0 0 calc((100% - 22px) / 2); }
  .locator-layout { grid-template-columns: 1fr; height: auto; }
  .map-view { height: 400px; }
  .results-list { border-right: none; border-bottom: 1px solid var(--border); }

  /* Footer accordion */
  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col {
    border-bottom: 1px solid rgba(255,255,255,0.1);
  }
  .footer-col h4 {
    margin: 0;
    padding: 18px 0;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .footer-toggle { display: inline; transition: transform .2s ease; font-size: 1.4rem; font-weight: 400; }
  .footer-col.expanded .footer-toggle { transform: rotate(45deg); }
  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height .3s ease, padding .3s ease;
    padding-bottom: 0;
  }
  .footer-col.expanded ul {
    max-height: 600px;
    padding-bottom: 18px;
  }
}

@media (max-width: 600px) {
  .container { padding: 0 16px; }
  section { padding: 50px 0; }
  .carousel { padding: 0 44px; }
